export const Schema = z.object({
    user: z.object({
        $利益点数: z.coerce.number().transform(v => _.clamp(v, 0, Infinity)).prefault(0),
    }).prefault({}),
    角色: z.record(z.string().describe('角色名'), z.object({
        _性别: z.string().prefault('未设定'),
        _与user的初始关系: z.string().prefault('陌生人'),
        _攻略动机: z.enum(['系统绑定', '自然兴趣']).prefault('系统绑定'),
        _user好感度: z.coerce.number().transform(v => _.clamp(v, -100, 100)).prefault(0),
        _攻略阶段: z.enum([
            '厌恶', '排斥', '冷淡', '无感',
            '留意', '接纳', '喜爱', '心动', '倾心',
        ]).prefault('无感'),
        当前攻略行为: z.string().prefault('尚未行动'),
        绑定系统: z.string().nullable().prefault(null),
        系统任务: z.string().nullable().prefault(null),
        系统积分: z.coerce.number().transform(v => _.clamp(v, 0, Infinity)).prefault(0),
        $利益贡献: z.coerce.number().transform(v => _.clamp(v, 0, Infinity)).prefault(0),
        持有物品: z.record(z.string().describe('物品名'), z.string()).prefault({}),
        心情: z.string().prefault('平静'),
    })).prefault({}),
    任务列表: z.record(z.string().describe('任务名'), z.object({
        描述: z.string().prefault(''),
        奖励: z.string().prefault(''),
        难度: z.enum(['简单', '普通', '困难', '史诗']).prefault('普通'),
        状态: z.enum(['可接取', '进行中', '已完成', '已失败']).prefault('可接取'),
    })).prefault({}),
    商城: z.record(z.string().describe('商品名'), z.object({
        描述: z.string().prefault(''),
        价格: z.coerce.number().transform(v => _.clamp(v, 0, Infinity)).prefault(0),
        库存: z.union([
            z.coerce.number().transform(v => _.clamp(v, 0, Infinity)),
            z.literal('无限'),
        ]).prefault('无限'),
        系统类别: z.string().nullable().prefault(null),
    })).prefault({}),
    系统日志: z.array(z.object({
        类型: z.string().prefault(''),
        内容: z.string().prefault(''),
        时间戳: z.coerce.number().prefault(() => Date.now()),
    })).transform(arr => arr.slice(-30))
        .prefault([]),
});
